// ---------------------------------------------------------------
// Build: reuse existing HTML (201-300) & JavaScript (301-400),
// renumber to 1-100 and 201-300.
// ---------------------------------------------------------------
let old = [];
try {
  old = JSON.parse(fs.readFileSync(OLD, "utf8"));
} catch (e) {
  console.error("Could not read existing questions.json:", e.message);
}

const oldHtml = old.filter((x) => x.category === "HTML").sort((a, b) => a.qNum - b.qNum);
const oldJs = old.filter((x) => x.category === "JavaScript").sort((a, b) => a.qNum - b.qNum);

const html = oldHtml.map((x, i) => ({
  qNum: 1 + i,
  questionText: x.questionText,
  options: x.options,
  correctAnswerIndex: x.correctAnswerIndex,
  category: "HTML",
}));

const js = oldJs.map((x, i) => ({
  qNum: 201 + i,
  questionText: x.questionText,
  options: x.options,
  correctAnswerIndex: x.correctAnswerIndex,
  category: "JavaScript",
}));

const all = [...html, ...css, ...js, ...php, ...cpp, ...react, ...bootstrap, ...general];

// Sanity: unique qNum, all have 4 options.
const seen = new Set();
const dups = [];
for (const item of all) {
  if (seen.has(item.qNum)) dups.push(item.qNum);
  seen.add(item.qNum);
}
if (dups.length) throw new Error("Duplicate qNum: " + dups.join(", "));

for (const item of all) {
  if (!Array.isArray(item.options) || item.options.length < 2) {
    throw new Error("Bad options at qNum " + item.qNum);
  }
  if (typeof item.correctAnswerIndex !== "number") {
    throw new Error("Bad correctAnswerIndex qNum " + item.qNum);
  }
}

fs.writeFileSync(OUT, JSON.stringify(all, null, 2) + "\n", "utf8");

const byCat = {};
all.forEach((x) => (byCat[x.category] = (byCat[x.category] || 0) + 1));
console.log("Wrote", all.length, "questions:");
console.log(byCat);